// Visualization tab for calc-value tasks. Renders the S1..S4 step
// progress bar plus the /calc/viz iframe. The iframe (viz.html
// generated by the S4 agent) already ships its own batch_size/seq_len
// controls + Recalculate button internally, so we don't duplicate them
// here — earlier versions had a parallel control strip above the
// iframe that hit the same /calc/compute endpoint, which produced two
// sets of buttons/totals confusing the user.

import { html } from "htm/preact";
import { useCallback, useEffect, useState } from "preact/hooks";

const STEPS = [
  { id: "s0_rough",      label: "S0: Rough",      ctrl: "S0_rough" },
  { id: "s1_analyze",    label: "S1: Analyze",     ctrl: "S1_analyze" },
  { id: "s2_graph",      label: "S2: Graph",       ctrl: "S2_graph" },
  { id: "s3_calculate",  label: "S3: Calculate",   ctrl: "S3_calculate" },
  { id: "s4_visualize",  label: "S4: Visualize",   ctrl: "S4_visualize" },
];

async function rerunStep(taskId, stepCtrl, setRerunState) {
  try {
    const r = await fetch(`/api/calc-theoretical-value/${taskId}/control`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "rerun_step", step: stepCtrl }),
    });
    if (r.ok) {
      setRerunState({ ok: true, step: stepCtrl });
    } else {
      const err = await r.json().catch(() => ({}));
      setRerunState({ ok: false, step: stepCtrl, error: err.detail || r.statusText });
    }
  } catch (e) {
    setRerunState({ ok: false, step: stepCtrl, error: e.message });
  }
}

export function CalcVizTab({ taskId }) {
  const [summary, setSummary] = useState(null);
  const [rerunState, setRerunState] = useState(null);

  const refreshSummary = useCallback(async () => {
    if (!taskId) return;
    try {
      const r = await fetch(`/api/calc-theoretical-value/${taskId}/calc/summary`, { cache: "no-store" });
      setSummary(r.ok ? await r.json() : null);
    } catch (e) { /* keep last */ }
  }, [taskId]);

  useEffect(() => {
    refreshSummary();
    const id = setInterval(refreshSummary, 5000);
    return () => clearInterval(id);
  }, [refreshSummary]);

  // Auto-clear rerun feedback after 5s.
  useEffect(() => {
    if (!rerunState) return;
    const id = setTimeout(() => setRerunState(null), 5000);
    return () => clearTimeout(id);
  }, [rerunState]);

  const vizReady = !!summary?.steps?.s4_visualize?.done;

  return html`
    <section class="panel calc-steps">
      <h2>Pipeline steps</h2>
      <div class="step-row">
        ${STEPS.map((s) => {
          const info = summary?.steps?.[s.id];
          const done = !!info?.done;
          return html`
            <div class=${`step ${done ? "done" : ""}`}>
              <span class="step-dot">${done ? "✓" : "·"}</span>
              <span class="step-label">${s.label}</span>
              ${s.id === "s2_graph" && info?.node_count != null
                ? html`<span class="muted">(${info.node_count} nodes)</span>` : null}
              ${s.id === "s3_calculate" && info?.node_count != null
                ? html`<span class="muted">(${info.node_count} scripts)</span>` : null}
              ${done ? html`
                <button class="btn ghost step-rerun"
                  title="Re-run ${s.ctrl} (wipes this step + all later steps)"
                  onClick=${() => rerunStep(taskId, s.ctrl, setRerunState)}>↻ re-run</button>
              ` : null}
            </div>
          `;
        })}
      </div>
      ${rerunState ? html`
        <div class=${`step-msg ${rerunState.ok ? "" : "step-msg-err"}`}>
          ${rerunState.ok
            ? `Re-running ${rerunState.step} — orchestrator restarted, refresh in a moment.`
            : `Failed to re-run ${rerunState.step}: ${rerunState.error || "unknown"}`}
        </div>
      ` : null}
    </section>

    ${vizReady ? html`
      <section class="panel calc-viz-legend">
        <h2>图例 <span class="muted small">（节点边框颜色 = 算子类别）</span></h2>
        <ul class="legend-list">
          <li>
            <span class="legend-swatch" style=${{ border: "2px solid #f85149" }}></span>
            <span class="legend-label"><strong>attention</strong></span>
            <span class="muted small">QKV proj / O proj / scaled_dot_product / rotary / bmm / split-slice-concat</span>
          </li>
          <li>
            <span class="legend-swatch" style=${{ border: "2px solid #d2991d" }}></span>
            <span class="legend-label"><strong>mlp</strong></span>
            <span class="muted small">gate_up_proj / down_proj / silu_and_mul / fused_moe / topk</span>
          </li>
          <li>
            <span class="legend-swatch" style=${{ border: "2px solid #3fb950" }}></span>
            <span class="legend-label"><strong>norm</strong></span>
            <span class="muted small">rmsnorm / layernorm</span>
          </li>
          <li>
            <span class="legend-swatch" style=${{ border: "2px solid #58a6ff" }}></span>
            <span class="legend-label"><strong>quant / embedding</strong></span>
            <span class="muted small">量化算子、nn.Embedding</span>
          </li>
          <li>
            <span class="legend-swatch" style=${{ border: "2px solid #484f58" }}></span>
            <span class="legend-label"><strong>other</strong></span>
            <span class="muted small">add（残差）/ identity / 未归类</span>
          </li>
        </ul>
      </section>

      <section class="panel calc-viz-panel">
        <h2>可视化</h2>
        <iframe class="calc-iframe"
          src=${`/api/calc-theoretical-value/${taskId}/calc/viz`}
          sandbox="allow-scripts allow-same-origin" />
      </section>
    ` : html`
      <section class="panel calc-viz-panel placeholder">
        <p class="muted">可视化在 S4 完成后才会出现。先去"粗略评估"或"详细审计" tab 看中间结果。</p>
      </section>
    `}
  `;
}
